// ── Qut Pay: проверка подписи webhook ─────────────────────────────
// Подпись: X-Webhook-Signature = 'sha256=' + HMAC-SHA256(secret, timestamp + '.' + rawBody), hex
// Метка времени: X-Webhook-Timestamp (unix, секунды), допуск ±300 с (защита от replay)
// Секрет: переменная окружения QUTPAY_WEBHOOK_SECRET (или n8n Variables $vars.QUTPAY_WEBHOOK_SECRET)
const TOLERANCE_SEC = 300;

const item = $input.first();
const headers = item.json.headers || {};
const hdr = (name) => String(headers[name] ?? headers[name.toLowerCase()] ?? '');

const signature = hdr('x-webhook-signature');
const timestamp = hdr('x-webhook-timestamp');

// 1. Секрет
let secret = '';
try { secret = $env.QUTPAY_WEBHOOK_SECRET || ''; } catch (e) { /* доступ к $env запрещён (N8N_BLOCK_ENV_ACCESS_IN_NODE) */ }
if (!secret) { try { secret = $vars.QUTPAY_WEBHOOK_SECRET || ''; } catch (e) { /* Variables недоступны */ } }
if (!secret) throw new Error('QUTPAY_WEBHOOK_SECRET не задан (переменная окружения n8n или n8n Variables)');

// 2. Сырое тело запроса — подпись считается по исходным байтам, а не по распарсенному JSON
if (!item.binary || !item.binary.data) {
  throw new Error('В узле Webhook включите опцию «Raw Body» — без неё подпись проверить нельзя');
}
let raw;
try {
  raw = (await helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) {
  raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
}

// 3. Формат заголовков и защита от повтора
if (!signature.startsWith('sha256=')) throw new Error('Нет заголовка X-Webhook-Signature');
if (!/^\d{1,12}$/.test(timestamp)) throw new Error('Нет или неверный X-Webhook-Timestamp');
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - Number(timestamp)) > TOLERANCE_SEC) {
  throw new Error('X-Webhook-Timestamp вне допуска ±' + TOLERANCE_SEC + ' с (проверьте часы сервера n8n)');
}

// 4. HMAC-SHA256 и сравнение за постоянное время
let crypto;
try {
  crypto = require('crypto');
} catch (e) {
  throw new Error('Модуль crypto недоступен в Code-узле: задайте NODE_FUNCTION_ALLOW_BUILTIN=crypto в окружении n8n');
}
const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + raw, 'utf8').digest('hex');
const given = signature.slice('sha256='.length).trim().toLowerCase();
const a = Buffer.from(expected, 'utf8');
const b = Buffer.from(given, 'utf8');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) throw new Error('Подпись webhook неверна');

// 5. Разбираем событие
const payload = JSON.parse(raw);
const invoice = payload.invoice || {};
return [{
  json: {
    event: payload.event,
    invoice,
    invoiceId: invoice.id ?? null,
    externalOrderId: invoice.externalOrderId ?? null,
    status: invoice.status ?? null,
    amount: invoice.amount ?? null,
    late: invoice.late === true,
    sentAt: payload.sentAt ?? null,
    delivery: hdr('x-webhook-delivery') || null,
  },
}];

